export function withAnalytics(Wrapped, eventName) {
  function WithAnalytics(props) {
    useEffect(() => track(eventName), []);
    return <Wrapped {...props} />;            // pass-through; wrapped component unaware
  }
  WithAnalytics.displayName =
    `withAnalytics(${Wrapped.displayName ?? Wrapped.name})`;
  return WithAnalytics;                        // applied once, at the export site
}
